static JavaScriptSerializer J(){return new JavaScriptSerializer(){MaxJsonLength=int.MaxValue,RecursionLimit=300};}static Dictionary<string,object>D(object o){return(Dictionary<string,object>)o;}static object[] A(object o){return((IEnumerable)o).Cast<object>().ToArray();}static double[] V(object o){return A(o).Select(Convert.ToDouble).ToArray();}static Point3d P(object o){var v=V(o);return new Point3d(v[0],v[1],v.Length>2?v[2]:0);}static double[] P3(Point3d p){return new[]{p.X,p.Y,p.Z};}static ObjectId Id(Database db,string h){return db.GetObjectId(false,new Handle(Convert.ToInt64(h,16)),0);}static object Get(object o,string n){return o.GetType().InvokeMember(n,BindingFlags.GetProperty,null,o,null);}static void Set(object o,string n,object v){o.GetType().InvokeMember(n,BindingFlags.SetProperty,null,o,new[]{v});}static object CO(Document d,string h){var a=Get(Application.AcadApplication,"ActiveDocument");return a.GetType().InvokeMember("HandleToObject",BindingFlags.InvokeMethod,null,a,new object[]{h});}
static Dictionary<string,object> Row(Entity e,Transaction tr){var r=new Dictionary<string,object>{{"handle",e.Handle.ToString()},{"type",e.GetRXClass().Name},{"layer",e.Layer},{"color",e.ColorIndex},{"linetype",e.Linetype},{"space",((BlockTableRecord)tr.GetObject(e.OwnerId,OpenMode.ForRead)).Name}};r["lineweight"]=(int)e.LineWeight;r["linetype_scale"]=e.LinetypeScale;try{var b=e.GeometricExtents;r["min"]=P3(b.MinPoint);r["max"]=P3(b.MaxPoint);}catch{}var p=e as Polyline;if(p!=null){r["closed"]=p.Closed;r["vertices"]=Enumerable.Range(0,p.NumberOfVertices).Select(k=>new[]{p.GetPoint2dAt(k).X,p.GetPoint2dAt(k).Y,p.GetBulgeAt(k)}).ToArray();}var l=e as Line;if(l!=null){r["start"]=P3(l.StartPoint);r["end"]=P3(l.EndPoint);}var ar=e as Arc;if(ar!=null){r["center"]=P3(ar.Center);r["radius"]=ar.Radius;r["start_angle"]=ar.StartAngle;r["end_angle"]=ar.EndAngle;}var ci=e as Circle;if(ci!=null){r["center"]=P3(ci.Center);r["radius"]=ci.Radius;}
var t=e as MText;if(t!=null){r["text"]=t.Contents;r["height"]=t.TextHeight;r["width"]=t.Width;r["location"]=P3(t.Location);r["attachment"]=t.Attachment.ToString();r["background"]=t.BackgroundFill;r["rotation"]=t.Rotation;r["style"]=((TextStyleTableRecord)tr.GetObject(t.TextStyleId,OpenMode.ForRead)).Name;}var tx=e as DBText;if(tx!=null){r["text"]=tx.TextString;r["height"]=tx.Height;r["location"]=P3(tx.Position);}var b2=e as BlockReference;if(b2!=null){var b=(BlockTableRecord)tr.GetObject(b2.BlockTableRecord,OpenMode.ForRead);r["block"]=b.Name;r["position"]=P3(b2.Position);r["rotation"]=b2.Rotation;r["scale"]=new[]{b2.ScaleFactors.X,b2.ScaleFactors.Y,b2.ScaleFactors.Z};}var ld=e as Leader;if(ld!=null){r["vertices"]=Enumerable.Range(0,ld.NumVertices).Select(k=>P3(ld.VertexAt(k))).ToArray();r["annotation"]=ld.Annotation.IsNull?null:ld.Annotation.Handle.ToString();}
var hatch=e as Hatch;if(hatch!=null){r["pattern"]=hatch.PatternName;r["pattern_scale"]=hatch.PatternScale;r["pattern_angle"]=hatch.PatternAngle;r["pattern_defs"]=hatch.NumberOfPatternDefinitions;r["loop_count"]=hatch.NumberOfLoops;try{r["area"]=hatch.Area;}catch{}var defs=new List<object>();for(int k=0;k<hatch.NumberOfPatternDefinitions;k++){var a=hatch.GetPatternDefinitionAt(k);defs.Add(new{angle=a.Angle,bx=a.BaseX,by=a.BaseY,ox=a.OffsetX,oy=a.OffsetY,dashes=a.GetDashes().Cast<double>().ToArray()});}r["definitions"]=defs;}
