var vp=e as Viewport;if(vp!=null){r["twist"]=vp.TwistAngle;r["number"]=vp.Number;r["center"]=P3(vp.CenterPoint);r["width"]=vp.Width;r["height"]=vp.Height;r["C"]=vp.CustomScale;r["target"]=P3(vp.ViewTarget);r["view_center"]=new[]{vp.ViewCenter.X,vp.ViewCenter.Y};r["frozen"]=vp.GetFrozenLayers().Cast<ObjectId>().Select(x=>((LayerTableRecord)tr.GetObject(x,OpenMode.ForRead)).Name).ToArray();}
