static ObjectId Layer(Database db,Transaction tr,string name,int color){var lt=(LayerTable)tr.GetObject(db.LayerTableId,OpenMode.ForRead);if(lt.Has(name))return lt[name];lt.UpgradeOpen();var l=new LayerTableRecord(){Name=name,Color=Autodesk.AutoCAD.Colors.Color.FromColorIndex(Autodesk.AutoCAD.Colors.ColorMethod.ByAci,(short)color),LineWeight=LineWeight.LineWeight018};var id=lt.Add(l);tr.AddNewlyCreatedDBObject(l,true);return id;}
static void VP(Viewport v,Dictionary<string,object>q,Database db,Transaction tr){v.Locked=false;if(q.ContainsKey("center"))v.CenterPoint=P(q["center"]);if(q.ContainsKey("target")){v.ViewDirection=Vector3d.ZAxis;v.ViewTarget=P(q["target"]);v.ViewCenter=Point2d.Origin;v.TwistAngle=0;}if(q.ContainsKey("C"))v.CustomScale=Convert.ToDouble(q["C"]);if(q.ContainsKey("height"))v.Height=Convert.ToDouble(q["height"]);if(q.ContainsKey("width"))v.Width=Convert.ToDouble(q["width"]);foreach(string key in new[]{"freeze","thaw"})if(q.ContainsKey(key)){var ll=new ObjectIdCollection();var lt=(LayerTable)tr.GetObject(db.LayerTableId,OpenMode.ForRead);foreach(object n in A(q[key]))if(lt.Has((string)n))ll.Add(lt[(string)n]);if(key=="freeze")v.FreezeLayersInViewport(ll.GetEnumerator());else v.ThawLayersInViewport(ll.GetEnumerator());}if(q.ContainsKey("twist"))v.TwistAngle=Convert.ToDouble(q["twist"]);v.On=true;v.Locked=true;}
[CommandMethod("CAD_ANNOTATION_RUN",CommandFlags.Modal | CommandFlags.NoHistory)]public void Run(){
try { RunCore(); } catch(System.Exception ex) {
