}}
void RunCore(){var doc=Application.DocumentManager.MdiActiveDocument;var job=J().Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(R,"job.json")));string report=(string)job["report"];if(!String.Equals(Path.GetFullPath(doc.Name),Path.GetFullPath((string)job["document"]),StringComparison.OrdinalIgnoreCase)){doc.Editor.WriteMessage("\nCAD_ANNOTATION_BLOCKED_WRONG_DOCUMENT");return;}
