if(job.ContainsKey("dim_styles"))foreach(object ds in A(job["dim_styles"])){var q=D(ds);var dt=(DimStyleTable)tr.GetObject(db.DimStyleTableId,OpenMode.ForRead);if(q.ContainsKey("edit")&&Convert.ToBoolean(q["edit"])){var er=(DimStyleTableRecord)tr.GetObject(dt[(string)q["name"]],OpenMode.ForWrite);er.Dimtxt=Convert.ToDouble(q["height"]);continue;}if(dt.Has((string)q["name"]))throw new System.Exception("STYLE_EXISTS");var sr=(DimStyleTableRecord)tr.GetObject(dt[(string)q["source"]],OpenMode.ForRead);var nr=new DimStyleTableRecord();nr.CopyFrom(sr);nr.Name=(string)q["name"];nr.Dimtxt=Convert.ToDouble(q["height"]);dt.UpgradeOpen();dt.Add(nr);tr.AddNewlyCreatedDBObject(nr,true);}
