if(job.ContainsKey("updates"))foreach(object o in A(job["updates"])){var q=D(o);var e=(Entity)tr.GetObject(Id(db,(string)q["handle"]),OpenMode.ForWrite);if(q.ContainsKey("layer"))e.LayerId=Layer(db,tr,(string)q["layer"],q.ContainsKey("color")?Convert.ToInt32(q["color"]):7);if(q.ContainsKey("color"))e.ColorIndex=Convert.ToInt32(q["color"]);if(q.ContainsKey("lineweight"))e.LineWeight=(LineWeight)Convert.ToInt32(q["lineweight"]);if(q.ContainsKey("linetype_scale"))e.LinetypeScale=Convert.ToDouble(q["linetype_scale"]);if(q.ContainsKey("rotate"))e.TransformBy(Matrix3d.Rotation(Convert.ToDouble(q["rotate"]),Vector3d.ZAxis,P(q["pivot"])));if(q.ContainsKey("shift"))e.TransformBy(Matrix3d.Displacement(P(q["shift"])-Point3d.Origin));if(q.ContainsKey("grip_move")){var gm=D(q["grip_move"]);var gg=new GripDataCollection();e.GetGripPoints(gg,1.0,5,Vector3d.ZAxis,GetGripPointsFlags.GripPointsOnly);var selected=new GripDataCollection();selected.Add(gg[Convert.ToInt32(gm["index"])]);e.MoveGripPointsAt(selected,P(gm["offset"])-Point3d.Origin,(MoveGripPointsFlags)0);}
var t=e as MText;if(t!=null){if(q.ContainsKey("text"))t.Contents=(string)q["text"];if(q.ContainsKey("location"))t.Location=P(q["location"]);if(q.ContainsKey("height"))t.TextHeight=Convert.ToDouble(q["height"]);if(q.ContainsKey("width"))t.Width=Convert.ToDouble(q["width"]);if(q.ContainsKey("background"))t.BackgroundFill=Convert.ToBoolean(q["background"]);if(q.ContainsKey("attachment"))t.Attachment=(AttachmentPoint)Enum.Parse(typeof(AttachmentPoint),(string)q["attachment"]);}var tx=e as DBText;if(tx!=null){if(q.ContainsKey("text"))tx.TextString=(string)q["text"];if(q.ContainsKey("height"))tx.Height=Convert.ToDouble(q["height"]);if(q.ContainsKey("width_factor"))tx.WidthFactor=Convert.ToDouble(q["width_factor"]);}
var pl=e as Polyline;if(pl!=null&&q.ContainsKey("points")){var aa=A(q["points"]);while(pl.NumberOfVertices>aa.Length)pl.RemoveVertexAt(pl.NumberOfVertices-1);for(int k=0;k<aa.Length;k++){var vv=V(aa[k]);if(k<pl.NumberOfVertices){pl.SetPointAt(k,new Point2d(vv[0],vv[1]));pl.SetBulgeAt(k,0);}else pl.AddVertexAt(k,new Point2d(vv[0],vv[1]),0,0,0);}}
var ld=e as Leader;if(ld!=null){if(q.ContainsKey("points")){while(ld.NumVertices>0)ld.RemoveLastVertex();foreach(object po in A(q["points"]))ld.AppendVertex(P(po));}if(q.ContainsKey("arrow"))ld.HasArrowHead=Convert.ToBoolean(q["arrow"]);if(q.ContainsKey("arrow_size"))ld.Dimasz=Convert.ToDouble(q["arrow_size"]);if(q.ContainsKey("arrow_block")){var bt0=(BlockTable)tr.GetObject(db.BlockTableId,OpenMode.ForRead);ld.Dimldrblk=bt0[(string)q["arrow_block"]];}}
var ha=e as Hatch;if(ha!=null&&q.ContainsKey("pattern")){ha.SetHatchPattern(q.ContainsKey("custom")&&Convert.ToBoolean(q["custom"])?HatchPatternType.CustomDefined:HatchPatternType.PreDefined,(string)q["pattern"]);ha.PatternScale=Convert.ToDouble(q["pattern_scale"]);ha.PatternAngle=Convert.ToDouble(q["pattern_angle"]);ha.EvaluateHatch(true);}
updated.Add(e.Handle.ToString());}
if(job.ContainsKey("no_masks")&&Convert.ToBoolean(job["no_masks"]))foreach(ObjectId bid in bt){var b=(BlockTableRecord)tr.GetObject(bid,OpenMode.ForRead);if(b.IsFromExternalReference)continue;foreach(ObjectId id in b){var t=tr.GetObject(id,OpenMode.ForRead)as MText;if(t!=null&&t.BackgroundFill){t.UpgradeOpen();t.BackgroundFill=false;updated.Add(t.Handle.ToString());}}}
if(job.ContainsKey("polylines"))foreach(object o in A(job["polylines"])){var q=D(o);var p=new Polyline();p.SetDatabaseDefaults(db);p.LayerId=Layer(db,tr,(string)q["layer"],q.ContainsKey("color")?Convert.ToInt32(q["color"]):7);p.ColorIndex=q.ContainsKey("color")?Convert.ToInt32(q["color"]):256;p.LineWeight=LineWeight.LineWeight018;var pp=A(q["points"]);for(int i=0;i<pp.Length;i++){var a=V(pp[i]);p.AddVertexAt(i,new Point2d(a[0],a[1]),a.Length>2?a[2]:0,0,0);}if(q.ContainsKey("lineweight"))p.LineWeight=(LineWeight)Convert.ToInt32(q["lineweight"]);if(q.ContainsKey("linetype_scale"))p.LinetypeScale=Convert.ToDouble(q["linetype_scale"]);p.Closed=q.ContainsKey("closed")&&Convert.ToBoolean(q["closed"]);if(q.ContainsKey("linetype"))p.Linetype=(string)q["linetype"];var target=q.ContainsKey("space")&&(string)q["space"]=="paper"?ps:ms;target.AppendEntity(p);tr.AddNewlyCreatedDBObject(p,true);created.Add(new{kind="polyline",id=q["id"],handle=p.Handle.ToString()});}
if(job.ContainsKey("dbtexts"))foreach(object z in A(job["dbtexts"])){var q=D(z);var sr=(DBText)tr.GetObject(Id(db,(string)q["template"]),OpenMode.ForRead);var t=new DBText();t.SetDatabaseDefaults(db);t.TextStyleId=sr.TextStyleId;t.Height=Convert.ToDouble(q["height"]);t.TextString=(string)q["text"];t.LayerId=Layer(db,tr,(string)q["layer"],7);t.ColorIndex=7;t.HorizontalMode=TextHorizontalMode.TextCenter;t.VerticalMode=TextVerticalMode.TextVerticalMid;t.Position=P(q["location"]);t.AlignmentPoint=P(q["location"]);t.WidthFactor=0.8;t.LineWeight=LineWeight.LineWeight018;ps.AppendEntity(t);tr.AddNewlyCreatedDBObject(t,true);t.AdjustAlignment(db);created.Add(new{kind="dbtext",id=q["id"],handle=t.Handle.ToString()});}
if(job.ContainsKey("text_clones"))foreach(object o in A(job["text_clones"])){var q=D(o);var t=(MText)((MText)tr.GetObject(Id(db,(string)q["template"]),OpenMode.ForRead)).Clone();t.Contents=(string)q["text"];t.Location=P(q["location"]);if(q.ContainsKey("height"))t.TextHeight=Convert.ToDouble(q["height"]);t.BackgroundFill=false;if(q.ContainsKey("attachment"))t.Attachment=(AttachmentPoint)Enum.Parse(typeof(AttachmentPoint),(string)q["attachment"]);if(q.ContainsKey("layer"))t.LayerId=Layer(db,tr,(string)q["layer"],7);if(q.ContainsKey("width"))t.Width=Convert.ToDouble(q["width"]);var target=q.ContainsKey("space")&&(string)q["space"]=="paper"?ps:ms;target.AppendEntity(t);tr.AddNewlyCreatedDBObject(t,true);mapping["text:"+(string)q["id"]]=t.Handle.ToString();created.Add(new{kind="text",id=q["id"],handle=t.Handle.ToString()});}
if(job.ContainsKey("leader_links"))foreach(object o in A(job["leader_links"])){var q=D(o);string th=(string)q["text"];if(mapping.ContainsKey(th))th=mapping[th];var ld=(Leader)tr.GetObject(Id(db,(string)q["handle"]),OpenMode.ForWrite);ld.Annotation=Id(db,th);}
if(job.ContainsKey("viewports"))foreach(object o in A(job["viewports"])){var q=D(o);VP((Viewport)tr.GetObject(Id(db,(string)q["handle"]),OpenMode.ForWrite),q,db,tr);}tr.Commit();}
