static object Styles(Database db){var rows=new List<object>();using(var tr=db.TransactionManager.StartTransaction()){var dt=(DimStyleTable)tr.GetObject(db.DimStyleTableId,OpenMode.ForRead);foreach(ObjectId id in dt){var d=(DimStyleTableRecord)tr.GetObject(id,OpenMode.ForRead);rows.Add(new{name=d.Name,height=d.Dimtxt,scale=d.Dimscale,textstyle=d.Dimtxsty.Handle.ToString()});}tr.Commit();}return rows;}
static void Read(Document doc,Dictionary<string,object>job){var rows=new List<Dictionary<string,object>>();var db=doc.Database;using(var tr=db.TransactionManager.StartTransaction()){var bt=(BlockTable)tr.GetObject(db.BlockTableId,OpenMode.ForRead);foreach(ObjectId bid in bt){var b=(BlockTableRecord)tr.GetObject(bid,OpenMode.ForRead);if(!b.IsLayout&&!job.ContainsKey("all_blocks"))continue;foreach(ObjectId id in b){var e=tr.GetObject(id,OpenMode.ForRead)as Entity;if(e!=null&&(!job.ContainsKey("only_hatches")||e is Hatch))rows.Add(Row(e,tr));}}tr.Commit();}foreach(var r in rows.Where(x=>((string)x["type"]).StartsWith("TDb"))){try{object o=CO(doc,(string)r["handle"]);var props=new Dictionary<string,object>();foreach(string n in new[]{"NameText","ScaleText","UpText","DownText","IndexLabel","DrawingLabel","Height","Scale","DimStyle","TextString","BackgroundFill","TextMask","Mask","WidthFactor","Text","DesText","ScaleFactors","TextHeight","TextLayer","LayoutRotation"})try{props[n]=Get(o,n);}catch{}r["props"]=props;}catch{}}File.WriteAllText((string)job["report"],J().Serialize(new{mode="READ_ONLY",document=doc.Name,entities=rows,dimstyles=Styles(db)}));doc.Editor.WriteMessage("\nREVISION_READ_COMPLETE");}
static void Parts(Entity e,List<object> rows,int depth){if(depth>4)return;var r=new Dictionary<string,object>{{"type",e.GetRXClass().Name},{"color",e.ColorIndex}};try{var b=e.GeometricExtents;r["min"]=P3(b.MinPoint);r["max"]=P3(b.MaxPoint);}catch{}var t=e as DBText;if(t!=null){r["text"]=t.TextString;r["height"]=t.Height;r["rotation"]=t.Rotation;r["position"]=P3(t.Position);rows.Add(r);return;}var m=e as MText;if(m!=null){r["text"]=m.Contents;r["height"]=m.TextHeight;r["rotation"]=m.Rotation;rows.Add(r);return;}var l=e as Line;if(l!=null){r["start"]=P3(l.StartPoint);r["end"]=P3(l.EndPoint);rows.Add(r);return;}var p=e as Polyline;if(p!=null){r["vertices"]=Enumerable.Range(0,p.NumberOfVertices).Select(k=>P3(p.GetPoint3dAt(k))).ToArray();rows.Add(r);return;}try{var c=new DBObjectCollection();e.Explode(c);if(c.Count==0)rows.Add(r);foreach(DBObject ob in c){try{var en=ob as Entity;if(en!=null)Parts(en,rows,depth+1);}finally{ob.Dispose();}}}catch{rows.Add(r);}}
static void Details(Document doc,Dictionary<string,object> job){var res=new List<object>();using(var tr=doc.Database.TransactionManager.StartTransaction()){foreach(object h0 in A(job["handles"])){var e=(Entity)tr.GetObject(Id(doc.Database,(string)h0),OpenMode.ForRead);var rows=new List<object>();Parts(e,rows,0);res.Add(new{handle=h0,parts=rows});}tr.Commit();}File.WriteAllText((string)job["report"],J().Serialize(res));}
